/**
 * @file The database, generated by scripts/fetch_games.py and bundled into the page by Bun,
 * so the built site is a single file that works offline and from file://.
 * @module data
 */
import db from '../data/games.json';

// The whole database: { algorithm_version, updated, games }.
export const database = db;

// Games with a drawable constellation.
export const games = db.games.filter((game) => game.constellation?.stars.length);
